# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.40.0/ankra-cli-darwin-arm64"
      sha256 "3ba95b97b85dad7a66568b05dc530a0276f5e1d9829ac5748db297972ae2a677"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.40.0/ankra-cli-darwin-amd64"
      sha256 "ec070d104272fd917b4e719dc1e5555a77dc7d77958583abc681677357daa5f4"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.40.0/ankra-cli-linux-arm64"
      sha256 "a5339c4a8530f342a0fb68c4281da799ce9059c4db09c554a4d9b6fd1c504dad"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.40.0/ankra-cli-linux-amd64"
